import React, { useState, useEffect } from "react";
import "./App.css";
import {
  FaFacebookF,
  FaInstagram,
  FaYoutube
} from "react-icons/fa";

const API_URL = "http://localhost:8000";

export default function App() {
  // Estados para empleados
  const [empleados, setEmpleados] = useState([]);
  const [nuevoEmpleado, setNuevoEmpleado] = useState({
    nombre: "", area: "", puesto: "", salario_mensual: 0, fecha_ingreso: ""
  });

  // Estados para periodos
  const [periodos, setPeriodos] = useState([]);
  const [nuevoPeriodo, setNuevoPeriodo] = useState({
    mes: 1, año: 2026, fecha_corte: "", total_general: 0
  });

  // Estados para planillas (solo campos de entrada)
  const [planillas, setPlanillas] = useState([]);
  const [nuevaPlanilla, setNuevaPlanilla] = useState({
    periodo_id: "",
    empleado_id: "",
    sueldo_base: 0,
    horas_extras_diurnas: 0,
    horas_extras_nocturnas: 0,
    horas_nocturnas: 0,
    subsidio_alimentacion: 0,
    bono_extra: 0,
    aplica_nocturnidad: false,
    quincena25_aplica: false
  });

  // Cargar datos al iniciar
  useEffect(() => {
    const cargarDatos = async () => {
      try {
        const [resEmp, resPer, resPla] = await Promise.all([
          fetch(`${API_URL}/empleado`),
          fetch(`${API_URL}/periodo`),
          fetch(`${API_URL}/planilla`)
        ]);
        if (resEmp.ok) setEmpleados(await resEmp.json());
        if (resPer.ok) setPeriodos(await resPer.json());
        if (resPla.ok) setPlanillas(await resPla.json());
      } catch (error) {
        console.error("Error cargando datos:", error);
      }
    };
    cargarDatos();
  }, []);

  // Crear empleado
  const crearEmpleado = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch(`${API_URL}/empleado/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(nuevoEmpleado),
      });
      if (res.ok) {
        const data = await res.json();
        setEmpleados([...empleados, data]);
        setNuevoEmpleado({ nombre: "", area: "", puesto: "", salario_mensual: 0, fecha_ingreso: "" });
      }
    } catch (error) {
      console.error("Error al crear empleado:", error);
    }
  };

  // Crear periodo
  const crearPeriodo = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch(`${API_URL}/periodo/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(nuevoPeriodo),
      });
      if (res.ok) {
        const data = await res.json();
        setPeriodos([...periodos, data]);
        setNuevoPeriodo({ mes: 1, año: 2026, fecha_corte: "", total_general: 0 });
      }
    } catch (error) {
      console.error("Error al crear periodo:", error);
    }
  };

  // Crear planilla (envía solo los campos de entrada)
  const crearPlanilla = async (e) => {
    e.preventDefault();
    if (!nuevaPlanilla.periodo_id || !nuevaPlanilla.empleado_id) {
      alert("Debes seleccionar un período y un empleado");
      return;
    }
    try {
      const res = await fetch(`${API_URL}/planilla/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          periodo_id: parseInt(nuevaPlanilla.periodo_id),
          empleado_id: parseInt(nuevaPlanilla.empleado_id),
          sueldo_base: nuevaPlanilla.sueldo_base,
          horas_extras_diurnas: nuevaPlanilla.horas_extras_diurnas,
          horas_extras_nocturnas: nuevaPlanilla.horas_extras_nocturnas,
          horas_nocturnas: nuevaPlanilla.horas_nocturnas,
          subsidio_alimentacion: nuevaPlanilla.subsidio_alimentacion,
          bono_extra: nuevaPlanilla.bono_extra,
          aplica_nocturnidad: nuevaPlanilla.aplica_nocturnidad,
          quincena25_aplica: nuevaPlanilla.quincena25_aplica
        }),
      });
      if (res.ok) {
        const data = await res.json();
        setPlanillas([...planillas, data]);
        setNuevaPlanilla({
          periodo_id: "",
          empleado_id: "",
          sueldo_base: 0,
          horas_extras_diurnas: 0,
          horas_extras_nocturnas: 0,
          horas_nocturnas: 0,
          subsidio_alimentacion: 0,
          bono_extra: 0,
          aplica_nocturnidad: false,
          quincena25_aplica: false
        });
      } else {
        const error = await res.json();
        alert(`Error: ${error.detail || "No se pudo registrar la planilla"}`);
      }
    } catch (error) {
      console.error("Error al crear planilla:", error);
      alert("Error de conexión con el backend");
    }
  };

  return (
    <div className="app">
      <header className="navbar">
        <div className="logo-container">
          <div className="logo-circle">★</div>
          <span className="logo-text">TEXACO</span>
        </div>
        <nav className="nav-links">
          <a href="#">Inicio</a>
          <a href="#">Empleados</a>
          <a href="#">Planillas</a>
          <a href="#">Prestaciones</a>
          <a href="#">Ausencias</a>
        </nav>
        <div className="right-section">
          <button className="login-btn">Login</button>
          <div className="social-icons">
            <FaFacebookF />
            <FaInstagram />
            <FaYoutube />
          </div>
        </div>
      </header>

      <section className="hero">
        <div className="overlay">
          <h1>
            Sistema de Control de
            <br />
            Planillas
          </h1>
        </div>
      </section>

      <section className="gestion">
        <h2>Gestión de personal</h2>
      </section>

      <div style={{ padding: "20px", background: "#efefef" }}>
        <div style={{ display: "flex", flexWrap: "wrap", gap: "20px" }}>
          {/* Formulario Empleados */}
          <div style={{ flex: 1, background: "white", padding: "20px", borderRadius: "8px" }}>
            <h3>➕ Agregar Empleado</h3>
            <form onSubmit={crearEmpleado}>
              <input type="text" placeholder="Nombre" value={nuevoEmpleado.nombre} onChange={e => setNuevoEmpleado({...nuevoEmpleado, nombre: e.target.value})} required />
              <input type="text" placeholder="Área" value={nuevoEmpleado.area} onChange={e => setNuevoEmpleado({...nuevoEmpleado, area: e.target.value})} required />
              <input type="text" placeholder="Puesto" value={nuevoEmpleado.puesto} onChange={e => setNuevoEmpleado({...nuevoEmpleado, puesto: e.target.value})} required />
              <input type="number" step="0.01" placeholder="Salario mensual" value={nuevoEmpleado.salario_mensual} onChange={e => setNuevoEmpleado({...nuevoEmpleado, salario_mensual: parseFloat(e.target.value)})} required />
              <input type="date" placeholder="Fecha ingreso" value={nuevoEmpleado.fecha_ingreso} onChange={e => setNuevoEmpleado({...nuevoEmpleado, fecha_ingreso: e.target.value})} required />
              <button type="submit">Guardar Empleado</button>
            </form>
            <hr />
            <h4>📋 Empleados Registrados</h4>
            <ul style={{ listStyle: "none", padding: 0 }}>
              {empleados.map(emp => (
                <li key={emp.id}><strong>{emp.nombre}</strong> - {emp.puesto} (${emp.salario_mensual})</li>
              ))}
            </ul>
          </div>

          {/* Formulario Períodos */}
          <div style={{ flex: 1, background: "white", padding: "20px", borderRadius: "8px" }}>
            <h3>📅 Agregar Período</h3>
            <form onSubmit={crearPeriodo}>
              <input type="number" placeholder="Mes (1-12)" value={nuevoPeriodo.mes} onChange={e => setNuevoPeriodo({...nuevoPeriodo, mes: parseInt(e.target.value)})} required />
              <input type="number" placeholder="Año" value={nuevoPeriodo.año} onChange={e => setNuevoPeriodo({...nuevoPeriodo, año: parseInt(e.target.value)})} required />
              <input type="date" placeholder="Fecha corte" value={nuevoPeriodo.fecha_corte} onChange={e => setNuevoPeriodo({...nuevoPeriodo, fecha_corte: e.target.value})} required />
              <button type="submit">Guardar Período</button>
            </form>
            <hr />
            <h4>📋 Períodos Registrados</h4>
            <ul style={{ listStyle: "none", padding: 0 }}>
              {periodos.map(per => (
                <li key={per.id}>Mes {per.mes}/{per.año} - Corte: {per.fecha_corte}</li>
              ))}
            </ul>
          </div>

          {/* Formulario Planillas con etiquetas claras */}
          <div style={{ flex: 1, background: "white", padding: "20px", borderRadius: "8px" }}>
            <h3>💰 Registrar Planilla</h3>
            <form onSubmit={crearPlanilla}>
              <label>Período:</label>
              <select value={nuevaPlanilla.periodo_id} onChange={e => setNuevaPlanilla({...nuevaPlanilla, periodo_id: e.target.value})} required>
                <option value="">Seleccione período</option>
                {periodos.map(per => <option key={per.id} value={per.id}>Período {per.mes}/{per.año} (corte {per.fecha_corte})</option>)}
              </select>

              <label>Empleado:</label>
              <select value={nuevaPlanilla.empleado_id} onChange={e => setNuevaPlanilla({...nuevaPlanilla, empleado_id: e.target.value})} required>
                <option value="">Seleccione empleado</option>
                {empleados.map(emp => <option key={emp.id} value={emp.id}>{emp.nombre} - {emp.puesto}</option>)}
              </select>

              <label>Sueldo base mensual (USD):</label>
              <input type="number" step="0.01" placeholder="Ej: 650.00" value={nuevaPlanilla.sueldo_base} onChange={e => setNuevaPlanilla({...nuevaPlanilla, sueldo_base: parseFloat(e.target.value)})} required />

              <label>Horas extras diurnas (cantidad):</label>
              <input type="number" step="0.5" placeholder="Horas trabajadas en horario diurno extra" value={nuevaPlanilla.horas_extras_diurnas} onChange={e => setNuevaPlanilla({...nuevaPlanilla, horas_extras_diurnas: parseFloat(e.target.value)})} />

              <label>Horas extras nocturnas (cantidad):</label>
              <input type="number" step="0.5" placeholder="Horas extra en horario nocturno" value={nuevaPlanilla.horas_extras_nocturnas} onChange={e => setNuevaPlanilla({...nuevaPlanilla, horas_extras_nocturnas: parseFloat(e.target.value)})} />

              <label>Horas nocturnas normales (dentro de jornada):</label>
              <input type="number" step="0.5" placeholder="Horas trabajadas en jornada nocturna" value={nuevaPlanilla.horas_nocturnas} onChange={e => setNuevaPlanilla({...nuevaPlanilla, horas_nocturnas: parseFloat(e.target.value)})} />

              <label>Subsidio de alimentación (USD):</label>
              <input type="number" step="0.01" placeholder="Monto fijo" value={nuevaPlanilla.subsidio_alimentacion} onChange={e => setNuevaPlanilla({...nuevaPlanilla, subsidio_alimentacion: parseFloat(e.target.value)})} />

              <label>Bono extra (USD):</label>
              <input type="number" step="0.01" placeholder="Otros bonos" value={nuevaPlanilla.bono_extra} onChange={e => setNuevaPlanilla({...nuevaPlanilla, bono_extra: parseFloat(e.target.value)})} />

              <label style={{ display: "block", margin: "5px 0" }}>
                <input type="checkbox" checked={nuevaPlanilla.aplica_nocturnidad} onChange={e => setNuevaPlanilla({...nuevaPlanilla, aplica_nocturnidad: e.target.checked})} /> Aplica nocturnidad (recargo adicional)
              </label>

              <label style={{ display: "block", margin: "5px 0" }}>
                <input type="checkbox" checked={nuevaPlanilla.quincena25_aplica} onChange={e => setNuevaPlanilla({...nuevaPlanilla, quincena25_aplica: e.target.checked})} /> Pagar Quincena 25 (50% del sueldo base, solo si ≤ $1,500)
              </label>

              <button type="submit">Registrar Planilla</button>
            </form>
            <hr />
            <h4>📋 Planillas Registradas</h4>
            <table style={{ width: "100%", borderCollapse: "collapse" }} border="1">
              <thead>
                <tr>
                  <th>ID</th><th>Empleado</th><th>Período</th>
                  <th>ISSS</th><th>AFP</th><th>ISR</th>
                  <th>Total Ingresos</th><th>Neto</th>
                </tr>
              </thead>
              <tbody>
                {planillas.map(pl => {
                  const emp = empleados.find(e => e.id === pl.empleado_id);
                  const per = periodos.find(p => p.id === pl.periodo_id);
                  return (
                    <tr key={pl.id}>
                      <td>{pl.id}</td>
                      <td>{emp ? emp.nombre : "?"}</td>
                      <td>{per ? `${per.mes}/${per.año}` : "?"}</td>
                      <td>{pl.monto_isss?.toFixed(2) ?? "0.00"}</td>
                      <td>{pl.monto_afp?.toFixed(2) ?? "0.00"}</td>
                      <td>{pl.monto_isr?.toFixed(2) ?? "0.00"}</td>
                      <td>{pl.total_ingresos?.toFixed(2) ?? "0.00"}</td>
                      <td><strong>${pl.monto_neto?.toFixed(2) ?? "0.00"}</strong></td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
